<?php
require __DIR__.'/config.php';
$pagina = $_GET['pagina'] ?? 'inicio';
$permitidas = ['inicio','produtos','enderecos','transportadores','fretes','relatorios','detalhes'];
if (!in_array($pagina,$permitidas,true)) $pagina='inicio';
$entidades = [
 'produtos'=>['titulo'=>'Produtos','singular'=>'Produto','campos'=>['nome'=>['Nome do produto','text',true],'descricao'=>['Descrição','text',false],'peso'=>['Peso (kg)','number',true]]],
 'enderecos'=>['titulo'=>'Endereços','singular'=>'Endereço','campos'=>['cep'=>['CEP','text',false],'rua'=>['Rua','text',true],'numero'=>['Número','text',true],'bairro'=>['Bairro','text',false],'cidade'=>['Cidade','text',true],'estado'=>['Estado (UF)','text',true]]],
 'transportadores'=>['titulo'=>'Transportadores','singular'=>'Transportador','campos'=>['nome'=>['Nome do transportador','text',true],'cnpj'=>['CNPJ','text',false],'telefone'=>['Telefone','text',false],'responsavel'=>['Nome do responsável','text',false]]]
];
if ($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  if (isset($entidades[$pagina])) {
   $campos=$entidades[$pagina]['campos'];$dados=[];
   foreach($campos as $campo=>$def){$dados[$campo]=trim((string)($_POST[$campo]??''));if($def[2] && $dados[$campo]==='')throw new Exception('Preencha os campos obrigatórios.');}
   if($pagina==='produtos' && (!is_numeric($dados['peso']) || (float)$dados['peso']<=0))throw new Exception('Informe um peso maior que zero.');
   $id=(int)($_POST['id']??0);
   if($id){$set=implode(', ',array_map(fn($c)=>"$c = :$c",array_keys($dados)));$sql="UPDATE $pagina SET $set WHERE id = :id";$dados['id']=$id;}
   else{$nomes=implode(', ',array_keys($dados));$marcas=implode(', ',array_map(fn($c)=>":$c",array_keys($dados)));$sql="INSERT INTO $pagina ($nomes) VALUES ($marcas)";}
   $pdo->prepare($sql)->execute($dados);redirecionar($pagina);
  }
  if($pagina==='fretes'){
   $data=$_POST['data_frete']??'';$trans=(int)($_POST['transportador_id']??0);$origem=(int)($_POST['origem_id']??0);$destino=(int)($_POST['destino_id']??0);
   $ids=$_POST['produto_id']??[];$qtds=$_POST['quantidade']??[];
   if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$data)||!$trans||!$origem||!$destino||$origem===$destino)throw new Exception('Informe data, transportador e endereços de origem e destino diferentes.');
   $itens=[];foreach($ids as $i=>$pid){$pid=(int)$pid;$q=(int)($qtds[$i]??0);if($pid<=0||$q<=0)throw new Exception('Escolha um produto e quantidade válida em todas as linhas.');$itens[]=[$pid,$q];}
   if(!$itens)throw new Exception('Adicione pelo menos um produto.');
   $pdo->beginTransaction();
   $stmt=$pdo->prepare('INSERT INTO fretes (data_frete,transportador_id,origem_id,destino_id) VALUES (?,?,?,?)');$stmt->execute([$data,$trans,$origem,$destino]);$freteId=$pdo->lastInsertId();
   $stmt=$pdo->prepare('INSERT INTO frete_produtos (frete_id,produto_id,quantidade) VALUES (?,?,?)');foreach($itens as [$pid,$q])$stmt->execute([$freteId,$pid,$q]);
   $pdo->commit();redirecionar('fretes','Frete gerado com sucesso!');
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$erro=$e->getMessage();}
}
// Download CSV compatível com Excel, filtrado por data.
if($pagina==='relatorios' && isset($_GET['baixar'])){
 $data=$_GET['data']??'';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$data))die('Data inválida');
 $stmt=$pdo->prepare('SELECT f.id,f.data_frete,t.nome AS transportador,eo.cidade AS origem,ed.cidade AS destino,p.nome AS produto,fp.quantidade,p.peso,(fp.quantidade*p.peso) AS peso_total FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id WHERE f.data_frete=? ORDER BY f.id');$stmt->execute([$data]);
 header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="relatorio_fretes_'.$data.'.csv"');
 $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['ID Frete','Data','Transportador','Origem','Destino','Produto','Quantidade','Peso unitário (kg)','Peso total (kg)'],';');foreach($stmt as $r)fputcsv($out,array_values($r),';');fclose($out);exit;
}
function fretesLista($pdo,$data=null){$sql='SELECT f.*,t.nome AS transportador,eo.cidade AS origem,ed.cidade AS destino FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id';if($data!==null)$sql.=' WHERE f.data_frete = ?';$sql.=' ORDER BY f.id DESC';$stmt=$pdo->prepare($sql);$stmt->execute($data!==null?[$data]:[]);return $stmt->fetchAll();}
$nomesMenu=['inicio'=>'Início','produtos'=>'Produtos','enderecos'=>'Endereços','transportadores'=>'Transportadores','fretes'=>'Fretes','relatorios'=>'Relatórios'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gerenciador Logístico</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 sidebar p-3"><h5 class="fw-bold mt-3">GERENCIADOR LOGÍSTICO</h5><small>Sistema de Controle de Fretes</small><nav class="mt-4"><?php foreach($nomesMenu as $chave=>$rotulo): ?><a class="<?= $pagina===$chave?'ativo':'' ?>" href="index.php?pagina=<?= $chave ?>"><?= h($rotulo) ?></a><?php endforeach; ?></nav></aside><main class="col-md-9 col-lg-10 conteudo">
<?php if(isset($_GET['msg'])): ?><div class="alert alert-success"><?= h($_GET['msg']) ?></div><?php endif; ?><?php if(isset($erro)): ?><div class="alert alert-danger"><?= h($erro) ?></div><?php endif; ?>
<?php if($pagina==='inicio'): ?>
<h2 class="titulo">Painel Inicial</h2><p class="subtitulo">Bem-vindo ao Gerenciador Logístico. Gerencie seus produtos, transportadores e fretes.</p><div class="row g-3 mt-2"><?php foreach(['produtos'=>'Produtos','transportadores'=>'Transportadores','fretes'=>'Fretes'] as $tab=>$rot): ?><div class="col-md-4"><div class="card p-3"><strong><?= $rot ?></strong><h2 class="my-3"><?= (int)$pdo->query("SELECT COUNT(*) FROM $tab")->fetchColumn() ?></h2><small class="subtitulo">Cadastrados no sistema</small></div></div><?php endforeach; ?></div>
<?php elseif(isset($entidades[$pagina])): $cfg=$entidades[$pagina];$edicao=null;if(isset($_GET['editar'])){$stmt=$pdo->prepare("SELECT * FROM $pagina WHERE id=?");$stmt->execute([(int)$_GET['editar']]);$edicao=$stmt->fetch();} ?>
<h2 class="titulo">Cadastro de <?= h($cfg['titulo']) ?></h2><p class="subtitulo">Cadastre, consulte e edite os registros do sistema.</p><div class="card p-4 mb-4" style="max-width:760px"><h5><?= $edicao?'Editar':'Novo' ?> <?= h($cfg['singular']) ?></h5><form method="post"><input type="hidden" name="id" value="<?= h($edicao['id']??'') ?>"><div class="row g-3 mt-1"><?php foreach($cfg['campos'] as $campo=>$def): ?><div class="col-md-<?= $pagina==='produtos'?12:6 ?>"><label class="form-label" for="<?= h($campo) ?>"><?= h($def[0]) ?></label><input class="form-control" id="<?= h($campo) ?>" name="<?= h($campo) ?>" type="<?= h($def[1]) ?>" <?= $def[1]==='number'?'step="0.01" min="0.01"':'' ?> value="<?= h($edicao[$campo]??'') ?>" <?= $def[2]?'required':'' ?>></div><?php endforeach; ?></div><button class="btn btn-primary mt-3">Salvar <?= h($cfg['singular']) ?></button><?php if($edicao): ?><a class="btn btn-outline-secondary mt-3" href="index.php?pagina=<?= $pagina ?>">Cancelar</a><?php endif; ?></form></div>
<h5><?= h($cfg['titulo']) ?> Cadastrados</h5><div class="table-responsive" style="max-width:850px"><table class="table table-striped table-bordered align-middle"><thead><tr><th>ID</th><?php foreach($cfg['campos'] as $campo=>$def): ?><th><?= h($def[0]) ?></th><?php endforeach; ?><th>Ações</th></tr></thead><tbody><?php foreach(buscarTodos($pdo,$pagina) as $registro): ?><tr><td><?= (int)$registro['id'] ?></td><?php foreach($cfg['campos'] as $campo=>$def): ?><td><?= h($registro[$campo]) ?></td><?php endforeach; ?><td><a class="btn btn-primary btn-sm" href="index.php?pagina=<?= $pagina ?>&editar=<?= (int)$registro['id'] ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php elseif($pagina==='fretes'): $produtos=buscarTodos($pdo,'produtos');$transportadores=buscarTodos($pdo,'transportadores');$enderecos=buscarTodos($pdo,'enderecos'); ?>
<h2 class="titulo">Cadastro de Fretes</h2><p class="subtitulo">Gere e consulte fretes com produtos e transportadores cadastrados.</p><div class="card p-4 mb-4" style="max-width:850px"><h5>Novo Frete</h5><?php if(!$produtos||!$transportadores||count($enderecos)<2): ?><div class="alert alert-warning">Antes de gerar um frete, cadastre ao menos um produto, um transportador e dois endereços.</div><?php endif; ?><form method="post"><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label">Data do frete</label><input type="date" name="data_frete" class="form-control" value="<?= date('Y-m-d') ?>" required></div><div class="col-md-6"><label class="form-label">Transportador</label><select class="form-select" name="transportador_id" required><option value="">Selecione</option><?php foreach($transportadores as $t): ?><option value="<?= $t['id'] ?>"><?= h($t['nome']) ?></option><?php endforeach; ?></select></div><?php foreach(['origem_id'=>'Endereço de origem','destino_id'=>'Endereço de destino'] as $campo=>$rot): ?><div class="col-md-6"><label class="form-label"><?= $rot ?></label><select class="form-select" name="<?= $campo ?>" required><option value="">Selecione</option><?php foreach($enderecos as $e): ?><option value="<?= $e['id'] ?>"><?= h($e['rua'].', '.$e['numero'].' - '.$e['cidade'].'/'.$e['estado']) ?></option><?php endforeach; ?></select></div><?php endforeach; ?></div><h6 class="mt-4">Produtos do Frete</h6><div id="linhas-produtos"></div><button type="button" class="btn btn-secondary btn-sm mt-2" onclick="adicionarProduto()">+ Adicionar Produto</button><div><button class="btn btn-primary mt-4">Gerar Frete</button></div></form></div>
<template id="linha-modelo"><div class="row g-2 linha-produto align-items-end mb-2"><div class="col-7"><label class="form-label">Produto</label><select name="produto_id[]" class="form-select" required><option value="">Selecione um produto</option><?php foreach($produtos as $pr): ?><option value="<?= $pr['id'] ?>"><?= h($pr['nome']) ?></option><?php endforeach; ?></select></div><div class="col-3"><label class="form-label">Quantidade</label><input type="number" min="1" name="quantidade[]" class="form-control" value="1" required></div><div class="col-2"><button type="button" class="btn btn-outline-danger w-100" onclick="removerProduto(this)">X</button></div></div></template>
<h5>Fretes Cadastrados</h5><?php tabelaFretes(fretesLista($pdo)); ?>
<?php elseif($pagina==='relatorios'): $data=$_GET['data']??date('Y-m-d'); ?>
<h2 class="titulo">Relatórios de Fretes</h2><p class="subtitulo">Consulte e baixe relatórios dos fretes por data.</p><div class="card p-4 mb-4" style="max-width:700px"><h5>Consultar Fretes</h5><form method="get"><input type="hidden" name="pagina" value="relatorios"><label class="form-label mt-2">Data do Frete</label><input class="form-control mb-3" type="date" name="data" value="<?= h($data) ?>" required><button class="btn btn-primary">Consultar Fretes</button><button class="btn btn-success" name="baixar" value="1">Baixar Relatório CSV</button></form></div><h5>Fretes Encontrados</h5><?php tabelaFretes(fretesLista($pdo,$data)); ?>
<?php elseif($pagina==='detalhes'): $id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT f.*,t.nome AS transportador,eo.rua AS origem_rua,eo.cidade AS origem_cidade,ed.rua AS destino_rua,ed.cidade AS destino_cidade FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id WHERE f.id=?');$stmt->execute([$id]);$f=$stmt->fetch(); ?>
<h2 class="titulo">Detalhes do Frete</h2><?php if(!$f): ?><p>Frete não encontrado.</p><?php else: ?><div class="card p-4"><p><strong>Frete #<?= $id ?></strong> — <?= h(date('d/m/Y',strtotime($f['data_frete']))) ?></p><p><strong>Transportador:</strong> <?= h($f['transportador']) ?></p><p><strong>Origem:</strong> <?= h($f['origem_rua'].' - '.$f['origem_cidade']) ?></p><p><strong>Destino:</strong> <?= h($f['destino_rua'].' - '.$f['destino_cidade']) ?></p><h5>Produtos transportados</h5><table class="table"><tr><th>Produto</th><th>Quantidade</th><th>Peso total</th></tr><?php $st=$pdo->prepare('SELECT p.nome,p.peso,fp.quantidade FROM frete_produtos fp JOIN produtos p ON p.id=fp.produto_id WHERE fp.frete_id=?');$st->execute([$id]);foreach($st as $item): ?><tr><td><?= h($item['nome']) ?></td><td><?= (int)$item['quantidade'] ?></td><td><?= h(number_format($item['peso']*$item['quantidade'],2,',','.')) ?> kg</td></tr><?php endforeach; ?></table></div><?php endif; ?><a class="btn btn-secondary mt-3" href="index.php?pagina=fretes">Voltar</a>
<?php endif; ?></main></div></div><script src="assets/app.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
<?php function tabelaFretes($fretes){ ?><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>ID</th><th>Transportador</th><th>Origem</th><th>Destino</th><th>Data</th><th>Ações</th></tr></thead><tbody><?php foreach($fretes as $f): ?><tr><td><?= (int)$f['id'] ?></td><td><?= h($f['transportador']) ?></td><td><?= h($f['origem']) ?></td><td><?= h($f['destino']) ?></td><td><?= h(date('d/m/Y',strtotime($f['data_frete']))) ?></td><td><a class="btn btn-primary btn-sm" href="index.php?pagina=detalhes&id=<?= (int)$f['id'] ?>">Detalhes</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$fretes): ?><p class="text-muted">Nenhum frete encontrado.</p><?php endif; ?></div><?php } ?>